sms[6] *= 1.889264154639560e+06; // CO2
sms[7] *= 2.968390795484913e+06; // CO
sms[8] *= 4.124237409798234e+07; // H2
sms[9] *= 8.248474819596468e+07; // H
sms[10] *= 2.598431970171023e+06; // O2
sms[11] *= 5.196863940342046e+06; // O
sms[12] *= 4.888847308845322e+06; // OH
sms[13] *= 2.519076112874398e+06; // HO2
sms[14] *= 2.444423654422661e+06; // H2O2
sms[15] *= 4.615299815794193e+06; // H2O
sms[16] *= 2.967966951578939e+06; // N2
